{
  "PROP-6a4369e9-inv-036": {
    "property_id": "PROP-6a4369e9-inv-036",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-036",
      "classification": "vulnerability",
      "code_path": "beacon_node/http_api/src/publish_blocks.rs::publish_column_sidecars::L522-529",
      "proof_trace": "publish_column_sidecars() publishes data columns to all computed subnets without validating against the node's sampling_subnets. The subnet is derived from column index (L525) and published directly (L529) with no check that subnet \u2208 network_globals.sampling_subnets, violating PeerDAS custody requirements.",
      "attack_scenario": "A block producer publishes all 128 data columns. The node publishes to all 128 subnets even though it's only subscribed to ~8 custody subnets, violating the PeerDAS spec and enabling network pollution/DOS through unsubscribed subnet publishing.",
      "checklist_id": "PROP-6a4369e9-inv-036"
    },
    "text": "Publishing data columns must only occur on subnets the node is subscribed to (custody/sampling).",
    "assertion": "forall col: published(col, subnet) => subscribed(subnet, custody) || subscribed(subnet, sampling)",
    "covers": "SG-010",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

